use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::process::Command;

/// Internal microservice for processing serialized job payloads
/// Accepts bincode-encoded job descriptors from the orchestrator

#[derive(Serialize, Deserialize, Debug)]
pub struct JobDescriptor {
    pub job_id: String,
    pub priority: u8,
    pub command: String,
    pub args: Vec<String>,
    pub env_vars: Vec<(String, String)>,
    pub working_dir: Option<String>,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct JobResult {
    pub job_id: String,
    pub exit_code: i32,
    pub stdout: String,
    pub stderr: String,
}

/// Executes a deserialized job descriptor
/// NOTE: This endpoint is only accessible from the orchestrator service
async fn execute_job(body: web::Bytes) -> HttpResponse {
    // Deserialize the incoming bincode payload
    let descriptor: JobDescriptor = match bincode::deserialize(&body) {
        Ok(d) => d,
        Err(e) => {
            return HttpResponse::BadRequest()
                .json(serde_json::json!({"error": format!("Deserialization failed: {}", e)}))
        }
    };

    log::info!("Executing job {}: {} {:?}", descriptor.job_id, descriptor.command, descriptor.args);

    // Execute the command from the job descriptor
    let mut cmd = Command::new(&descriptor.command);
    cmd.args(&descriptor.args);

    if let Some(ref dir) = descriptor.working_dir {
        cmd.current_dir(dir);
    }

    for (key, value) in &descriptor.env_vars {
        cmd.env(key, value);
    }

    let output = match cmd.output() {
        Ok(o) => o,
        Err(e) => {
            return HttpResponse::InternalServerError()
                .json(serde_json::json!({"error": format!("Execution failed: {}", e)}))
        }
    };

    let result = JobResult {
        job_id: descriptor.job_id,
        exit_code: output.status.code().unwrap_or(-1),
        stdout: String::from_utf8_lossy(&output.stdout).to_string(),
        stderr: String::from_utf8_lossy(&output.stderr).to_string(),
    };

    HttpResponse::Ok().json(result)
}

/// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

/// Metrics endpoint for Prometheus scraping
async fn metrics() -> HttpResponse {
    HttpResponse::Ok()
        .content_type("text/plain")
        .body("# HELP jobs_processed Total jobs processed\njobs_processed 0\n")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init_from_env(env_logger::Env::default().default_filter_or("info"));

    let bind_addr = std::env::var("BIND_ADDR").unwrap_or_else(|_| "0.0.0.0:8080".to_string());
    log::info!("Starting job executor on {}", bind_addr);

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/execute", web::post().to(execute_job))
            .route("/health", web::get().to(health))
            .route("/metrics", web::get().to(metrics))
    })
    .bind(&bind_addr)?
    .workers(4)
    .run()
    .await
}
